sources":["https://app.powerbi.com/view?r=eyJrIjoiNjk4NmRmZjctMzg5Yi00OTQxLTg2ZjgtNTc2NWUyN2I2ZTRjIiwidCI6IjEwNmQ2ZDMyLTU2ODktNGMwZi1hNTdkLTI2MzFmMWZkMWYyOCIsImMiOjl9"]},"province":null},{"import_key":"96f76fcb1abf788cf137d222","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[]},"province":null},{"import_key":"f6f14d8dc5ceca9e1851ddfc","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[{"operation_code":"D2022159","year":2022,"line":"IDIS-REACT","beneficiary":"UNIQO CUSTOM ENGINEERING, S.L.","feder_beneficiary_id":"ES51II27","operation_name":"UNIQO CUSTOM ENGINEERING, S.L.","description":"El modelo de negocio que se presenta a continuación es UNIQO CUSTOM ENGINEERING, un servicio de ingeniería mecánica, inicialmente basado en tres pilares fundamentales, el diseño mecánico, prototipado rápido y fabricación de componentes totalmente funcionales, todo ello de una manera eficiente y, sobre todo, personalizada. Ahora Uniqo Custom Engineering se apoya también en una nueva gama de productos fabricados con tecnología 4.0 para el sector ciclismo y triatlón a través de la denominación comercial de UNIQO CUSTO BIKES. Esta nueva denominación comercial engloba todos el conocimiento desarrollado en tecnología 4.0 de los últimos años poniéndolo a disposición de un sector muy competitivo como es el ciclismo y triatlón. Para poder cumplir con todos estos objetivos y dar un servicio diferenciador y único a nuestros clientes me he basado en la tecnología de Fabricación Aditiva o Impresión 3D.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":3409.0,"eu_cofinancing_percent":100.0,"province":"Huesca","municipality":"Huesca","municipality_code":"22125","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=668","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":668,"source_updated":"2025-05-29"}],"related_company_operations":[{"operation_code":"2022071","year":2022,"line":"TDI-FEDER (antecedente)","beneficiary":"UNIQO CUSTOM ENGINEERING, S.L.","feder_beneficiary_id":"ES51II27","operation_name":"UNIQO CUSTOM ENGINEERING, SL","description":"\"Uniqo Custom Engineering comienza a invertir en I+D+i para la generación de productos para el triatlón y ciclismo. Los comienzos son a demanda de un triatleta de Huesca, el cual nos consulta si podemos fabricar este tipo de producto, y nos ponemos a trabajar en 2019, durante la pandemia. Se va diseñando y fabricando prototipos y se ve que es un producto totalmente abordable, es más, se cree que se puede aportar un valor añadido trabajando diseños específicos para cada cliente. de hecho así ha sido, no hay dos diseños iguales. Nuestro fuerte es el diseño y la experiencia en ingeniería. Se apuesta por generar diseños únicos y personalizados, adaptados a cada deportista, que se adapten perfectamente a su posición aerodinámica y le aporten comodidad y ergonomía. Se decide crear una nueva linea de marca llamada UNIQO CUSTOM BIKES, dependiente de la ingeniería de UNIQO CUSTOM ENGINEERING, para poder dar forma a este proyecto y diferenciarlo de la actividad de Ingenieria de Diseño Mecánico y Proyectos, y distribución de impresoras 3D y escáner 3D. \"","start_date":"01/01/2021","end_date":"31/12/2021","feder_operation_cost":36661.61,"eu_cofinancing_percent":50.0,"province":"Huesca","municipality":"Huesca","municipality_code":"22125","inter